    public BLTSandwichBuilder()
    {
        _sandwich = new Sandwich();
    }

    public void AddBread()
    {
        _sandwich.Bread = "White";
    }

    public void AddMeat()
    {
        _sandwich.Meat = "Bacon";
    }

    public void AddCheese()
    {
        _sandwich.Cheese = "None";
    }

    public void AddVegetables()
    {
        _sandwich.Vegetables = "Lettuce, Tomato";
    }

    public void AddSauces()
    {
        _sandwich.Sauces = "Mayonnaise";
    }

    public Sandwich GetSandwich()
    {
        return _sandwich;
    }
}

//Clase concreta que implementa la interfaz ISandwichBuilder y que construye un sandwich tipo Club
public class ClubSandwichBuilder : ISandwichBuilder
{
    private Sandwich _sandwich;

    public ClubSandwichBuilder()
    {
        _sandwich = new Sandwich();
    }

    public void AddBread()
