```c
#include <stdio.h>
#include <math.h>

typedef struct point3 {
    double x, y, z;
} point3;

typedef struct matrix3 {
    point3 x_axis, y_axis, z_axis, translation;
} matrix3;

// Функция для создания матрицы
matrix3 MatrixFromNormal(point3 normal) {
    matrix3 result;

    double length = sqrt(normal.x * normal.x + normal.y * normal.y + normal.z * normal.z);
    point3 z_axis = {normal.x / length, normal.y / length, normal.z / length};
    point3 x_axis = {0, 0, 0};
    point3 y_axis = {0, 0, 0};

    if (z_axis.y == 0 && z_axis.z == 0) {
        x_axis.x = 1;
        y_axis.y = 1;
    }
    else {
        x_axis.x = z_axis.z;
        x_axis.y = -z_axis.z;
        x_axis.z = 0;

        double x_length = sqrt(x_axis.x * x_axis.x + x_axis.y * x_axis.y);

        x_axis.x /= x_length;
        x_axis.y /= x_length;

        y_axis.x = -z_axis.y * z_axis.z;
        y_axis.y = z_axis.x * z_axis.z;
        y_axis.z = z_axis.x * z_axis.y;

        double y_length = sqrt(y_axis.x * y_axis.x + y_axis.y * y_axis.y + y_axis.z * y_axis.z);

        y_axis.x /= y_length;
        y_axis.y /= y_length;
        y_axis.z /= y_length;
    }

    result.x_axis = x_axis;
    result.y_axis = y_axis;
    result.z_axis = z_axis;
    result.translation = (point3){0, 0, 0};

    return result;
}

// Функция для печати матрицы
void printMatrix(matrix3 m) {
    printf("Matrix: \n");
    printf("[%f, %f, %f]\n", m.x_axis.x, m.y_axis.x, m.z_axis.x);
    printf("[%f, %f, %f]\n", m.x_axis.y, m.y_axis.y, m.z_axis.y);
    printf("[%f, %f, %f]\n", m.x_axis.z, m.y_axis.z, m.z_axis.z);
    printf("[%f, %f, %f]\n", m.translation.x, m.translation.y, m.translation.z);
}

int main() {
    point3 normal1 = {0, 0, 1};
    point3 normal2 = {0, 1, 1};

    matrix3 result1 = MatrixFromNormal(normal1);
    matrix3 result2 = MatrixFromNormal(normal2);

    printMatrix(result1);
    printf("\n");
    printMatrix(result2);

    return 0;
}
```

